    def parse_version(version):
        # Split off build metadata (after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (after '-')
        if '-' in version_part:
            version_nums, prerelease = version_part.split('-', 1)
        else:
            version_nums = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_nums.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1, [])

        # Convert identifiers to comparable form
        converted = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers compare numerically and sort before non-digit
                converted.append((0, int(identifier)))
            else:
                # Non-digit identifiers compare by ASCII
                converted.append((1, identifier))

        return (0, converted)

    def version_key(version):
        major, minor, patch, prerelease_ids = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_ids))

    # Sort with stable sort to preserve input order for equal precedence
    return sorted(versions, key=version_key)

